const severityClass = (severity: string) => `severity-${severity.toLowerCase()}`;

function PageHeader({ eyebrow, title, subtitle, action }: { eyebrow?: string; title: string; subtitle?: string; action?: ReactNode }) {
  return <div className="page-header"><div><div className="page-eyebrow">{eyebrow ?? "AI CODER / WORKSPACE"}</div><h1>{title}</h1>{subtitle && <p>{subtitle}</p>}</div>{action && <div className="page-header-action">{action}</div>}</div>;
}

function Button({ children, onClick, variant = "primary", icon, disabled, className = "", type = "button" }: { children: ReactNode; onClick?: () => void; variant?: "primary" | "secondary" | "quiet" | "danger"; icon?: ReactNode; disabled?: boolean; className?: string; type?: "button" | "submit" }) {
  return <button type={type} className={`app-button app-button-${variant} ${className}`} onClick={onClick} disabled={disabled}>{icon}{children}</button>;
}

function PanelTitle({ title, eyebrow, action }: { title: string; eyebrow?: string; action?: ReactNode }) {
  return <div className="panel-title-row"><div>{eyebrow && <span className="panel-eyebrow">{eyebrow}</span>}<h3>{title}</h3></div>{action}</div>;
}

function MetricCard({ label, value, change, icon, tone = "cyan", delay = 0 }: { label: string; value: string; change: string; icon: ReactNode; tone?: string; delay?: number }) {
  return <motion.div className={`metric-card metric-${tone}`} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.35, delay }}><div className="metric-top"><span>{label}</span><span className="metric-icon">{icon}</span></div><div className="metric-value">{value}</div><div className="metric-change"><span>↗</span> {change} <span className="metric-period">vs last month</span></div></motion.div>;
}

function MiniLegend({ items }: { items: { label: string; color: string }[] }) {
  return <div className="mini-legend">{items.map((item) => <span key={item.label}><i style={{ background: item.color }} />{item.label}</span>)}</div>;
}

