export function CodeReviewPage() {
  const { selectedFile, setSelectedFile, code, setCode, analysis, setAnalysis } = useWorkspace();
  const [busy, setBusy] = useState(false);
  const [activeStep, setActiveStep] = useState(-1);
  const [selectedIssue, setSelectedIssue] = useState<string | null>(null);
  const [tab, setTab] = useState("Findings");
  const fileInput = useRef<HTMLInputElement>(null);
  const activeFile = demoFiles.find((file) => file.name === selectedFile) ?? demoFiles[0];
  const issues = analysis?.issues ?? [];

  const selectFile = (filename: string) => {
    const next = demoFiles.find((file) => file.name === filename);
    if (next) { setSelectedFile(next.name); setCode(next.code); setAnalysis(null); setSelectedIssue(null); }
  };
  const runAnalysis = async () => {
    setBusy(true); setActiveStep(0); setAnalysis(null);
    try {
      for (let step = 0; step < pipelineSteps.length; step += 1) { setActiveStep(step); await new Promise((resolve) => window.setTimeout(resolve, 205)); }
      const result = await analyzeCode(code, activeFile.language);
      setAnalysis(result); setSelectedIssue(result.issues[0]?.id ?? null); setActiveStep(pipelineSteps.length);
      toast.success("Review complete", { description: `${result.issues.length} actionable findings · ${result.duration}` });
    } catch (error) { toast.error("Review could not finish", { description: error instanceof Error ? error.message : "Check the code and retry." }); }
    finally { setBusy(false); }
  };
  const uploadFile = async (file?: File) => {
    if (!file) return;
    if (file.size > 200_000) { toast.error("File is too large", { description: "Upload a source file under 200 KB for this demo." }); return; }
    try { const text = await file.text(); setSelectedFile(file.name); setCode(text); setAnalysis(null); toast.success("Source file loaded", { description: file.name }); }
    catch { toast.error("Could not read that file", { description: "Choose a plain-text source file and try again." }); }
  };
  const chosen = issues.find((issue) => issue.id === selectedIssue);
  const [, navigate] = useLocation();

  return <div className="page page-review"><PageHeader eyebrow="WORKSPACE / SOURCE ANALYSIS" title="Code review" subtitle="Read the code, inspect the signal, and decide what ships." action={<div className="header-actions"><Button variant="secondary" onClick={() => navigate("/refactor")} icon={<Sparkles size={15} />}>Refactor</Button><Button variant="secondary" onClick={() => navigate("/testing")} icon={<FlaskConical size={15} />}>Generate tests</Button><Button disabled={busy} onClick={runAnalysis} icon={busy ? <Activity className="spin-icon" size={15} /> : <ScanLineIcon />}>{busy ? "Analyzing…" : "Analyze code"}</Button></div>} />
    <div className="review-toolbar"><div className="file-crumb"><span className={`file-ext ext-${activeFile.language.slice(0, 2)}`}>{activeFile.label.slice(0, 2).toUpperCase()}</span><select aria-label="Select source file" value={selectedFile} onChange={(event) => selectFile(event.target.value)}>{demoFiles.map((file) => <option key={file.name} value={file.name}>{file.name}</option>)}</select><ChevronDown size={13} /><span className="crumb-divider" /><span className="branch-label"><GitBranch size={13} /> main</span><span className="file-dirty-dot" title="Local changes" /></div><div className="review-toolbar-actions"><span className="autosave-label"><span /> Saved locally</span><button className="text-button" onClick={() => fileInput.current?.click()}><Upload size={14} /> Upload file</button><input ref={fileInput} type="file" accept=".py,.js,.jsx,.ts,.tsx,.java,.sql,.go,.rb,.txt" hidden onChange={(event) => { void uploadFile(event.target.files?.[0]); event.target.value = ""; }} /></div></div>
    <div className="review-workspace"><section className="editor-panel"><div className="editor-panel-header"><div className="editor-tab-active"><FileCode2 size={14} />{selectedFile}<span>×</span></div><div className="editor-toolbar"><span>{activeFile.label}</span><span>⌘ S</span></div></div><CodeEditor value={code} language={activeFile.language} onChange={setCode} minHeight="calc(100vh - 340px)" focusedLines={chosen ? [chosen.line] : []} /><div className="editor-foot"><span><span className="status-pulse" /> Language server ready</span><span>UTF-8 <i /> LF <i /> {activeFile.language === "python" ? "4 spaces" : "2 spaces"}</span></div></section>
      <aside className="review-inspector"><div className="inspector-tabs">{["Findings", "Pipeline"].map((name) => <button key={name} className={tab === name ? "active" : ""} onClick={() => setTab(name)}>{name}{name === "Findings" && analysis && <span className="tab-count">{analysis.issues.length}</span>}</button>)}</div>
        {busy ? <div className="analysis-progress"><div className="analysis-orbit"><span /><span /><i><Sparkles size={18} /></i></div><span className="panel-eyebrow">AI REVIEW ENGINE</span><h3>Reading between<br />the lines.</h3><p>Combining static signals with code context to find what matters.</p><div className="analysis-step-list">{pipelineSteps.map((step, index) => <div key={step} className={`analysis-step ${index < activeStep ? "complete" : index === activeStep ? "current" : ""}`}>{index < activeStep ? <CheckCircle2 size={14} /> : index === activeStep ? <span className="step-spinner" /> : <span className="step-empty" />}<span>{step}</span>{index === activeStep && <small>RUNNING</small>}</div>)}</div><div className="analysis-progress-bar"><span style={{ width: `${Math.min(((activeStep + 1) / pipelineSteps.length) * 100, 100)}%` }} /></div><small className="progress-caption">Analysis stays local in this interactive demo</small></div> : tab === "Pipeline" ? <PipelineVisual /> : analysis ? <div className="inspector-findings"><div className="review-score-block"><div className="review-score-ring" style={{ "--score": `${analysis.score}%` } as React.CSSProperties}><span>{analysis.score}<small>/100</small></span></div><div><small>CODE HEALTH</small><strong>{analysis.score >= 85 ? "Strong foundation" : "Needs attention"}</strong><p>Analysis completed in {analysis.duration}</p></div><button className="icon-button" onClick={() => toast("Score breakdown", { description: "Weighted from maintainability, readability, security, performance, and complexity." })} aria-label="Score details"><CircleHelp size={14} /></button></div><div className="review-summary"><span className="panel-eyebrow">SUMMARY</span><p>{analysis.summary}</p></div><div className="finding-count-row"><span>Findings <strong>{analysis.issues.length}</strong></span><button className="text-button" onClick={() => toast("Finding filter", { description: "Showing all severities in this sample." })}><Filter size={13} /> Filter</button></div><div className="issue-list">{analysis.issues.length ? analysis.issues.map((issue, index) => <IssueCard key={issue.id} issue={issue} index={index} selected={selectedIssue === issue.id} onSelect={() => setSelectedIssue(issue.id)} />) : <div className="empty-state compact"><span className="empty-icon"><BadgeCheck size={19} /></span><strong>Clean pass</strong><p>No actionable issues found in this snippet.</p></div>}</div>{chosen && <div className="issue-detail"><span className="panel-eyebrow">RECOMMENDED ACTION</span><p>{chosen.recommendation}</p><div className="complexity-compare"><span>Current <strong>{chosen.complexity}</strong></span><ArrowRight size={13} /><span>Suggested <strong>{chosen.id === "perf-nested-loop" ? "O(n + m)" : "Safer"}</strong></span></div><Button variant="secondary" className="full-width" onClick={() => navigate("/refactor")} icon={<WandSparkles size={14} />}>Generate a fix</Button></div>}</div> : <div className="review-empty"><div className="empty-icon"><Sparkles size={19} /></div><span className="panel-eyebrow">READY WHEN YOU ARE</span><h3>Start with a review.</h3><p>Run a fresh analysis to see security, performance, and maintainability findings for this file.</p><Button onClick={runAnalysis} icon={<ScanLineIcon />}>Analyze this file</Button><small>Demo findings are generated locally</small></div>}
      </aside></div>
  </div>;
}

function PipelineVisual() {
  const stages = ["Source", "Parser", "AST analysis", "Security agent", "Performance agent", "AI reasoning", "Review judge", "Refactor + tests", "Validated report"];
  return <div className="pipeline-visual"><span className="panel-eyebrow">MULTI-STAGE REVIEW</span><h3>Analysis pipeline</h3><p>Focused agents work in sequence, with checks around every suggestion.</p>{stages.map((stage, index) => <div className={`pipeline-node-row ${index < 3 ? "is-done" : ""}`} key={stage}><span>{index < 3 ? <Check size={11} /> : String(index + 1).padStart(2, "0")}</span><strong>{stage}</strong>{index < stages.length - 1 && <i />}</div>)}<div className="pipeline-version">PARSER v2.4 <span>·</span> ANALYSIS MODE: DEEP</div></div>;
}

export function RefactorPage() {
  const { selectedFile, code, setCode } = useWorkspace();
  const [refactored, setRefactored] = useState<string | null>(null);
  const [changes, setChanges] = useState<string[]>([]);
  const [validation, setValidation] = useState<string[]>([]);
  const [busy, setBusy] = useState(false);
  const [testBeforeApply, setTestBeforeApply] = useState(true);
  const [stage, setStage] = useState(-1);
  const language = demoFiles.find((file) => file.name === selectedFile)?.language ?? "python";
  const runRefactor = async () => {
    setBusy(true); setStage(0);
    try {
      for (let i = 0; i < 5; i += 1) { setStage(i); await new Promise((resolve) => window.setTimeout(resolve, 220)); }
      const result = await refactorCode(code, language); setRefactored(result.code); setChanges(result.changes); setValidation(result.validation); setStage(5);
      toast.success("Refactor ready", { description: testBeforeApply ? "Validated patch with generated tests." : "Patch generated. Run validation before applying." });
    } catch { toast.error("Could not generate a refactor", { description: "Try again or change the selected code." }); }
    finally { setBusy(false); }
  };
  const copyCode = async () => { if (!refactored) return; try { await navigator.clipboard.writeText(refactored); toast.success("Copied refactored code"); } catch { toast.error("Clipboard unavailable", { description: "Select the code and copy it manually." }); } };
  const downloadCode = () => { if (!refactored) return; const blob = new Blob([refactored], { type: "text/plain" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = selectedFile.replace(/(\.[^.]+)?$/, ".refactored$1"); anchor.click(); URL.revokeObjectURL(url); toast.success("Download started"); };
  const applyPatch = () => { if (!refactored) return; setCode(refactored); toast.success("Patch applied to the workspace", { description: "Your review editor now contains the refactored version." }); };

  return <div className="page page-refactor"><PageHeader eyebrow="WORKSPACE / TRANSFORM" title="AI refactor" subtitle={`A reviewable patch for ${selectedFile}. Test it before it touches your source.`} action={<Button disabled={busy} onClick={runRefactor} icon={busy ? <RefreshCw className="spin-icon" size={15} /> : <Sparkles size={15} />}>{busy ? "Generating…" : refactored ? "Generate again" : "Generate refactor"}</Button>} />
    <div className="refactor-meta-bar"><div className="refactor-meta-left"><span className="file-ext ext-py">PY</span><strong>{selectedFile}</strong><span className="diff-stat"><i />{refactored ? `+${Math.max(4, changes.length)} improvements` : "Ready to compare"}</span></div><div className="refactor-meta-right"><label className="toggle-check"><input type="checkbox" checked={testBeforeApply} onChange={(event) => setTestBeforeApply(event.target.checked)} /><span className="custom-checkbox"><Check size={11} /></span> Run tests before applying</label><span className="refactor-meta-divider" /><Button variant="secondary" onClick={() => void copyCode()} disabled={!refactored} icon={<Copy size={14} />}>Copy</Button><Button variant="secondary" onClick={downloadCode} disabled={!refactored} icon={<Download size={14} />}>Download</Button><Button onClick={applyPatch} disabled={!refactored} icon={<Check size={14} />}>Apply patch</Button></div></div>
    <div className="diff-label-row"><span><i className="diff-old-icon">−</i> Original</span><span><i className="diff-new-icon">+</i> Refactored</span><span className="diff-mode">SIDE-BY-SIDE DIFF</span></div>
    <div className="diff-editor-shell"><div className="diff-editor-caption"><div><FileCode2 size={13} /> {selectedFile}</div><div>{refactored ? <><span className="diff-added">+{Math.max(8, changes.length * 2)}</span><span className="diff-removed">−7</span></> : <span className="muted-caption">Generate a refactor to compare changes</span>}</div></div><div className="diff-editor-inner"><Suspense fallback={<div className="editor-loading" role="status"><span className="step-spinner" /> Loading diff editor…</div>}><DiffEditor height="min(54vh, 540px)" language={language} original={code} modified={refactored ?? code} theme="ai-coder-dark" options={{ readOnly: true, renderSideBySide: true, minimap: { enabled: false }, scrollBeyondLastLine: false, wordWrap: "on", automaticLayout: true, fontFamily: "'JetBrains Mono', monospace", fontSize: 12, lineHeight: 22, padding: { top: 14 }, lineNumbers: "on", overviewRulerBorder: false, renderIndicators: true, diffWordWrap: "on", scrollbar: { verticalScrollbarSize: 7, horizontalScrollbarSize: 7 } }} /></Suspense></div></div>
    <div className="refactor-bottom-grid"><section className="panel changes-panel"><PanelTitle eyebrow="CHANGE SUMMARY" title="What gets better" />{refactored ? <div className="change-list">{changes.map((change) => <div key={change}><span><Check size={13} /></span>{change}</div>)}</div> : <div className="panel-placeholder"><Sparkles size={15} /> Generate a patch to review its impact.</div>}</section><section className="panel validation-panel"><PanelTitle eyebrow="SAFETY CHECKS" title="Validation workflow" action={validation.length > 0 ? <span className="validation-status"><CheckCircle2 size={13} /> ALL PASSED</span> : null} />{busy ? <div className="validation-steps">{["Generate refactor", "Run static analysis", "Generate tests", "Run tests", "Compare security", "Validation"].map((item, index) => <div className={`validation-step ${index <= stage ? "step-active" : ""}`} key={item}><span>{index < stage ? <Check size={11} /> : index === stage ? <span className="step-spinner" /> : String(index + 1).padStart(2, "0")}</span>{item}</div>)}</div> : validation.length ? <div className="validation-pass-list">{validation.map((item) => <div key={item}><CheckCircle2 size={14} /><span>{item}</span></div>)}</div> : <div className="validation-empty"><span className="validation-empty-icon"><ShieldCheck size={17} /></span><p>Run a refactor to generate the patch, validate syntax, and exercise the suggested tests.</p></div>}</section></div>
  </div>;
}

